function r0Title(title,body){return `<header class="r0-title"><h2 tabindex="-1">${re(title)}</h2><p>${re(body)}</p></header>`}
function r0Setup(s){return `<div class="r0-entry"><div class="r0-intro">${avatar(s)}<p class="eyebrow">Ваш CEO</p>${r0Title('Познакомьтесь с Fabric','Я помогу разобраться в проектах, сохранить решения и продолжить работу с нужного места.')}</div><section class="r0-card"><p>Подключите исполнителя, затем выберите папку проекта. Я соберу обзор и помогу с первым шагом.</p><div class="r0-footer">${rb('Подключить исполнителя','identity',true)}</div></section>${hint('Имя, образ и стиль общения можно изменить в настройках.')}</div>`}
function r0Provider(s){const descriptions={unchecked:'Выберите инструмент, которым Fabric будет выполнять работу.',checking:'Проверяем запуск, вход и возможности подключения…',ready:'Исполнитель подключён. Можно знакомиться с проектом.',missing:'Приложение агента не найдено на этом компьютере.',auth:'Нужно войти в аккаунт агента.',unsupported:'Эта версия не поддерживает необходимые возможности Fabric.',failed:'Не удалось проверить подключение. Настройки сохранены.'};return `<div class="r0-entry">${r0Title('Кто будет выполнять работу','Fabric сохраняет проекты и решения. Базового исполнителя можно заменить в любой момент.')}<div class="r0-provider-grid">${['claude-code','codex'].map(p=>`<button class="r0-provider ${s.provider===p?'selected':''}" data-r0="provider" data-value="${p}" aria-pressed="${s.provider===p}"><span class="r0-provider-mark">${p==='codex'?'⌘':'✳'}</span><strong>${providerName(p)}</strong><small>${p==='codex'?'Работа с кодом и терминалом':'Работа с кодом и контекстом'}</small></button>`).join('')}</div>${card(providerName(s.provider),`<p role="status">${descriptions[s.readiness]}</p>${['missing','auth','unsupported'].includes(s.readiness)?detail('Как подключить',`<ol><li>${s.readiness==='auth'?'Откройте установленный агент и войдите в свой аккаунт.':'Установите или обновите агент из официального источника.'}</li><li>Вернитесь в Fabric и повторите проверку.</li></ol><p>Пароли и ключи в чат Fabric вводить не нужно.</p><a class="button" href="${s.provider==='codex'?'https://developers.openai.com/codex/cli/':'https://code.claude.com/docs/en/setup'}" target="_blank" rel="noreferrer">Открыть инструкцию</a>`):''}<div class="r0-footer">${s.readiness==='ready'?(s.pendingResume?rb('Продолжить работу','resume-pending',true,`data-value="${s.pendingResume}"`):rl('Выбрать проект','r0-source',s.estate)):rb(s.readiness==='checking'?'Проверяем…':'Проверить подключение','probe',true,s.readiness==='checking'?'disabled':'')}</div>`)}${detail('Проверить состояния макета',`<p>Имитируется результат проверки; настоящий агент не запускается.</p><label class="field">Результат следующей проверки<select data-r0-field="probeOutcome"><option value="ready">Доступен</option><option value="missing">Не установлен</option><option value="auth">Нужен вход</option><option value="unsupported">Версия не подходит</option><option value="failed">Ошибка</option></select></label>`)}${rl('Посмотреть сохранённую работу','r0-home',s.estate)}</div>`}
function r0Source(s){return `<div class="r0-entry">${r0Title('С какого проекта начнём?','Выберите папку. Я изучу доступные материалы и покажу, что здесь происходит.')}<div class="r0-segment" role="group" aria-label="Источник проекта">${[['project','Один проект'],['collection','Папка с проектами'],['url','URL репозитория']].map(([id,label])=>rb(label,'source-mode',false,`data-value="${id}" aria-pressed="${s.sourceMode===id}"`)).join('')}</div>${card(s.sourceMode==='collection'?'Найти мои проекты':s.sourceMode==='url'?'Подключить репозиторий':'Папка проекта',s.sourceMode==='url'?`<label class="field">URL репозитория<input type="url" data-r0-field="url" placeholder="https://…" value="${re(s.url)}"></label>${hint('Fabric сначала проверит доступ. Клонирование потребует выбора папки и отдельного разрешения.')}${rb('Изучить репозиторий','scan',true)}`:`<div class="r0-folder"><span class="r0-folder-icon" aria-hidden="true">▱</span><div><strong>${s.source?re(s.source.split('/').pop()):'Выберите папку на компьютере'}</strong><p class="meta">${s.source?re(s.source):'Название и описание проекта Fabric найдёт сам'}</p></div>${folderPickerControl({id:'r0-folder',label:'Папка проекта',value:s.source})}</div>${s.source?`<div class="r0-footer">${rb('Изучить проект','scan',true)}</div>`:''}`)}${detail('Что будет прочитано',`<p>Описание, структура, инструкции проекта и состояние Git — только в выбранной папке. Без запуска команд из README, изменений файлов и отправки секретов.</p><p>Название берётся из папки. Предположения о цели можно исправить после обзора.</p>`)}${s.readiness!=='ready'?`<p class="r0-warning">Для изучения проекта нужно подключить исполнителя.</p>${rl('Подключить','r0-provider',s.estate)}`:''}</div>`}
function r0Discovery(s){const scan=s.scan;return `<div class="r0-entry">${r0Title(scan==='running'?'Знакомлюсь с проектом':['candidates','candidates-partial'].includes(scan)?'Нашёл проекты':'Чтение проекта остановлено',s.pendingSource||'Сначала выберите папку')}<section class="r0-card">${scan==='running'?`<ol class="r0-scan-steps">${['Читаю описание и структуру','Сверяю инструкции и Git','Собираю решения и открытые вопросы','Готовлю обзор и следующий шаг'].map((t,i)=>`<li class="${i<s.scanStep?'done':i===s.scanStep?'active':''}"><span>${i<s.scanStep?'✓':i+1}</span>${t}${i===s.scanStep?'<small>Сейчас</small>':''}</li>`).join('')}</ol><p role="status">${['Читаю описание','Проверяю доступные источники','Собираю контекст','Подготавливаю обзор'][s.scanStep]}</p>${rb('Остановить чтение','scan-cancel')}`:['candidates','candidates-partial'].includes(scan)?`<p>${scan==='candidates-partial'?'Часть источников недоступна. Выберите из найденных.':'Выберите проекты, которые составят общий контекст. Первый выбранный станет главным.'}</p><div class="r0-source-list">${s.candidates.map(({name:n,path})=>`<div class="r0-source-row"><label class="r0-source-choice"><input type="checkbox" data-r0="candidate-toggle" data-value="${re(path)}" ${s.chosenSources.includes(path)?'checked':''}><span><strong>${re(n)}</strong><small>${re(path)}</small></span></label>${s.chosenSources.includes(path)?rb(s.primarySource===path?'Главный':'Сделать главным','candidate-primary',false,`data-value="${re(path)}" aria-pressed="${s.primarySource===path}"`):''}</div>`).join('')}</div><p class="meta">Остальные останутся внутри проекта как связанные источники. Их ссылки и назначение войдут в контекст CEO и задач.</p>${rb('Продолжить с выбранными','candidate-import',true,s.chosenSources.length?'':'disabled')}`:`<p role="alert">${({denied:'Нет доступа к папке. Выберите другую папку или восстановите доступ.',failed:'Исполнитель прервал чтение. Можно повторить с сохранённым выбором.',cancelled:'Чтение отменено. Файлы не изменены.',empty:'В выбранной папке проекты не найдены. Выберите другую папку.',idle:'Папка ещё не выбрана.'})[scan]||'Обзор уже сохранён.'}</p><div class="r0-footer">${rl('Выбрать папку','r0-source',s.estate)}${s.pendingSource?rb('Повторить чтение','scan',true):''}</div>`}</section></div>`}
// Every screen carries a page heading; the single action of an empty screen is its primary one.
function empty(s){return r0Title('Проект ещё не выбран','Fabric соберёт контекст и поможет выбрать следующий шаг.')+card('Начните с одного проекта',`<div class="r0-footer">${rl('Выбрать папку проекта',s.readiness==='ready'?'r0-source':'r0-provider',s.estate).replace('class="button"','class="button primary"')}</div>`)}
function r0Home(s){const open=s.board.filter(b=>b.state==='open'),p=current(s);return `<header class="r0-profile">${avatar(s,true)}<div><h2 tabindex="-1">${re(s.name)}</h2><p class="meta">Ваш CEO · ${s.readiness==='ready'?providerName(s.provider):'исполнитель не подключён'}</p></div><div class="r0-pulse"><span>Ритм работы</span><div aria-label="Активность в макете">${[1,3,2,5,3,6,4].map((n,i)=>`<button title="День ${i+1}: ${n} событий примера" aria-label="День ${i+1}: ${n} событий примера" style="--r0-bar:${n}"></button>`).join('')}</div><small>Проекты: ${s.projects.length} · события: ${s.history.length}</small></div>${p?`<button type="button" class="home-resume" data-r0="${activeProjectRun(s,p.id)?'open-run':'select-project'}" data-value="${activeProjectRun(s,p.id)?.id||p.id}"><span class="meta">Где остановились · ${re(p.name)}</span><strong>${re(p.tasks.find(t=>t.id===(activeProjectRun(s,p.id)||s.runs[p.id])?.task)?.title||p.checkpoint)}</strong><span aria-hidden="true">↗</span></button>`:''}</header><div class="r0-dashboard"><div class="r0-stack">${card('На доске',open.length?open.slice(0,3).map(b=>`<div class="r0-row"><div><strong>${re(b.title)}</strong><p class="meta">${re(s.projects.find(p=>p.id===b.project)?.name)} · ${b.task?'Результат ждёт вас':'Нужно решение'}</p></div>${rb('Разобрать','open-ticket',false,`data-value="${b.id}"`)}</div>`).join(''):`<p>Сейчас нет вопросов, требующих вашего решения.</p>${hint('Вопросы и результаты появятся здесь по ходу работы.')}`)}${card('Мои проекты',`<div class="r0-projects">${s.projects.map(x=>`<button class="r0-project-tile" data-r0="select-project" data-value="${x.id}"><span class="r0-project-icon">${re(x.name[0].toUpperCase())}</span><strong>${re(x.name)}</strong><small>${x.tasks.length?'Задачи: '+x.tasks.length:'Обзор готов'}</small></button>`).join('')||'<p>Проекты ещё не добавлены.</p>'}</div><div class="r0-footer">${rl('Добавить проект','r0-source',s.estate)}${rb('Найти в памяти','memory-open',false,'data-value="all"')}</div>`)}</div><aside class="r0-stack">${renderTeamWorkspace(s)}${card('Live',`<p class="r0-live"><span></span>${Object.values(s.runsById).some(r=>r.status==='running')?'Агенты работают':'Нет активных запусков'}</p>${s.history.slice(0,5).map(e=>`<div class="r0-event">${re(e.title)}</div>`).join('')||hint('Здесь будут начало работы, ожидание и результаты.')}`)}</aside></div>`}
function r0Project(s){const p=current(s);if(!p)return empty(s);const questions=s.board.filter(b=>b.project===p.id&&b.state!=='done');return `${r0Title(p.name,p.goal||'Обзор готов. Выберите первый полезный результат вместе с Fabric.')}${rb('Память проекта','memory-open',false,`data-value="${p.id}"`)}<div class="r0-dashboard"><div class="r0-stack">${card('Доска внимания',questions.length?questions.map(b=>`<div class="r0-row"><div><strong>${re(b.title)}</strong><p class="meta">${b.state==='deferred'?'На следующий раз':b.task?'Результат ждёт вас':'Нужно решение'}</p></div>${rb('Разобрать','open-ticket',false,`data-value="${b.id}"`)}</div>`).join(''):'<p class="meta">Пока нет вопросов, требующих вашего решения.</p>')}${p.tasks.length?card('Работа по проекту',p.tasks.map(t=>`<div class="r0-row"><button class="r0-subject-link" data-r0="discuss" data-value="task:${t.id}" title="Обсудить задачу с Fabric">${re(t.title)}</button><span class="chip">${re(({planned:'В плане',running:'В работе',stopped:'Остановлено',review:'На проверке',done:'Принято'})[t.state])}</span></div>`).join('')+`<div class="r0-footer">${rl('Открыть план','r0-plan',s.estate)}${rb('Следующий шаг','plan-chat')}</div>`):card('Начнём с полезного шага',`<p>${p.empty?'Расскажите, что хотите создать.':'Предлагаю проверить основной пользовательский сценарий.'}</p><div class="r0-footer">${rb('Обсудить с Fabric','plan-chat',true)}</div>`)}${card('Что это за проект',`<p>${re(projectInsightText(p))}</p><span class="chip">${p.partial?'Прочитано частично':p.empty?'Нужен контекст':'Предположение Fabric'}</span>${detail('Источники и границы обзора',facts(p)+hint('Демонстрационные источники макета. Реальные файлы не читались.'))}${rb('Уточнить обзор','discuss',false,`data-value="insight:${p.id}"`)}${p.partial?rb('Повторить чтение','scan-current'):''}`)}</div><aside class="r0-stack">${renderTeamWorkspace(s,p.id)}${card('Где остановились',`<p>${re(checkpoint(s,p))}</p>${rb('Разобраться с Fabric','plan-chat')}`)}${card('Контекст проекта',sourceList(p))}${rb('Добавить вопрос на доску','topic')}</aside></div>`}

function r0Context(s){const p=current(s);return `<p><strong>${re(p?.tasks.find(t=>t.id===s.run?.task)?.title||'Текущая задача')}</strong></p><dl class="r0-facts"><div><dt>Зачем</dt><dd>${re(p?.goal||'Цель ещё не принята')}</dd></div><div><dt>Последний шаг</dt><dd>${s.run?.status==='review'?'Исполнитель передал результат по этой задаче.':s.run?.status==='stopped'?'Исполнитель остановлен; можно восстановить контекст.':'Исполнитель работает с контекстом этой задачи.'}</dd></div><div><dt>Рабочая копия</dt><dd>${re(s.run?.context?.primary||p?.source||'Не выбрана')} · main · 4c9a72e</dd></div><div><dt>Изменения</dt><dd>Подробности изменений — в журнале исполнителя; в макете файлы не изменяются</dd></div><div><dt>Проверки</dt><dd>Независимая проверка результата ещё не выполнена</dd></div><div><dt>Дальше</dt><dd>Сверить diff, завершить правку, выполнить проверки</dd></div></dl>${p?detail('Связанные источники и версия пакета',`<pre>${re(JSON.stringify(s.run?.context||firstReleaseContext(s),null,2))}</pre>`):''}${hint('Пакет содержит резюме, подробный последний участок и ссылки на журнал. Пример; не внутренние рассуждения модели.')}`}
function r0Work(s){const p=current(s),r=s.run;if(!p)return empty(s);if(!r||r.project!==p.id)return r0Title('Исполнитель','Выберите задачу из плана, чтобы начать работу.')+rl('Открыть план','r0-plan',s.estate);const resolved=teamRunState(s,r),accepted=resolved==='done';const status=accepted?'Результат принят':resolved==='changes'?'Передано на доработку':{running:'Работает',stopping:'Останавливается',stopped:'Остановлен',unknown:'Остановка не подтверждена',review:'Результат на проверке'}[r.status];return `${r0Title(providerName(r.provider),p.tasks.find(t=>t.id===r.task)?.title||'Работа по проекту')}<div class="r0-work-bar"><span class="chip">${status}</span><span class="meta">${re(p.name)} · main · ${re(r.session)}</span>${r.status==='running'?rb('Остановить','stop'):r.status==='stopped'&&s.taskRuns[r.task]===r.id?rb('Продолжить…','continue',true):r.status==='unknown'?(s.forceStopRun===r.id?`<span class="meta">Остановить эту сессию принудительно? Несохранённые изменения могут потеряться.</span>${rb('Отмена','force-cancel')}${rb('Остановить принудительно','force-confirm',true)}`:rb('Проверить остановку','check-stop')+rb('Остановить принудительно','force-stop')):''}${rb(resolved==='review'?'Разобрать результат':'Обсудить с Fabric','discuss',resolved==='review',`data-value="task:${r.task}"`)}</div><div class="r0-dashboard"><section class="r0-card r0-console"><header><strong>Терминал</strong><small>Пример вывода</small></header><pre>${re('$ '+(r.provider==='codex'?'codex':'claude')+'\n\nЗадача: '+(p.tasks.find(t=>t.id===r.task)?.title||'Продолжить работу')+'\nКонтекст проекта загружен.\nРабочая копия: '+p.source+'\n\n'+(r.status==='running'?'› Изучаю изменения и готовлю следующий шаг…':r.status==='stopped'?'Процесс завершён. Контекст доступен для продолжения.':r.status==='stopping'?'Запрос остановки отправлен. Ожидаем завершения процесса…':r.status==='unknown'?'Нет подтверждения завершения. Новый исполнитель пока не запускается.':'Результат передан на проверку.'))}</pre>${r.status==='running'?`<label class="field"><span>Сообщение исполнителю</span><input data-r0-field="terminalInput" placeholder="Уточнить задачу…" value="${re(s.terminalInput||'')}"></label>${rb('Отправить уточнение','terminal-send')}`:''}</section><aside class="r0-stack">${card('Контекст работы',r0Context(s)+rb('Скопировать контекст','copy-context')+rb('Память проекта','memory-open',false,`data-value="${p.id}"`))}${detail('Сессии этой задачи',Object.values(s.runsById).filter(x=>x.task===r.task&&x.project===p.id).map(x=>`<div class="r0-row"><span class="meta">${providerName(x.provider)} · ${re(x.session)}${x.id===r.id?' · открыта':''}</span>${rb('Открыть','open-run',false,`data-value="${x.id}"`)}</div>`).join(''))}${detail('Сценарии проверки макета',`<p>Только имитация событий; настоящий процесс не запускается.</p>${rb('Показать результат','deliver',false,r.status!=='running'?'disabled':'')}<label class="field">Следующая остановка<select data-r0-field="stopOutcome"><option value="stopped">Процесс завершился</option><option value="timeout">Нет подтверждения</option></select></label>`)}${s.continuation?card('Как продолжить',`<p>Старый процесс остановлен. История и изменения сохраняются.</p>${rb('Прежний разговор','resume',false,`data-value="native" ${!r.nativeResume?'disabled':''}`)}${rb('Новая сессия Claude Code','resume',false,'data-value="claude-code"')}${rb('Новая сессия Codex','resume',false,'data-value="codex"')}${detail('Что получит новый агент',r0Context(s))}`):''}</aside></div>`}
function r0Board(s){return r0Title('Доска внимания','Откройте вопрос. Fabric поможет разобраться и сохранить следующий шаг.')+`<div class="r0-stack">${s.board.map(b=>`<section class="r0-card r0-ticket"><button class="r0-ticket-open" data-r0="open-ticket" data-value="${b.id}"><span class="r0-ticket-icon">◌</span><span><strong>${re(b.title)}</strong><small>${re(s.projects.find(p=>p.id===b.project)?.name)} · ${b.state==='done'?'Итог сохранён':b.state==='deferred'?'На следующий раз':'Нужен разбор'}</small></span><span aria-hidden="true">↗</span></button>${b.outcome?hint(b.outcome.summary):hint('Обсудить с Fabric → сформировать итог → запустить работу')}<div class="r0-footer">${rb(b.messages?.length?'Продолжить разбор':'Разобрать с Fabric','open-ticket',true,`data-value="${b.id}"`)}${b.state==='open'?rb('На следующий раз','defer',false,`data-value="${b.id}"`):rb('Вернуть на доску','reopen',false,`data-value="${b.id}"`)}</div></section>`).join('')||card('Сейчас решений не требуется','<p>Вопросы появятся здесь, когда понадобится ваше участие.</p>')}${rb('Обсудить новый вопрос','topic')}${detail('Повторяемый обзор',`<p>Fabric собирает вопросы по заданному циклу. Запуск работы проходит отдельную проверку.</p>${rb(s.cycle?'Приостановить обзор':'Включить ежедневный обзор','cycle')}`)}</div>`}
function r0Plan(s){const p=current(s);if(!p)return empty(s);return r0Title('План · '+p.name,p.goal||'Выберите первый результат вместе с Fabric.')+card('Ближайшая работа',`${p.tasks.map((t,i)=>`<div class="r0-plan-row"><span class="r0-plan-number">${i+1}</span><div><button class="r0-subject-link" data-r0="discuss" data-value="task:${t.id}" title="Обсудить задачу с Fabric">${re(t.title)}</button><p class="meta">${re(({planned:'В плане',running:'В работе',stopped:'Остановлено',review:'На проверке',done:'Принято'})[t.state]||t.state)} · ${providerName(s.runsById[s.taskRuns[t.id]]?.provider||s.provider)}</p></div>${t.state==='planned'?rb('Начать работу','run',true,`data-value="${t.id}"`):['running','stopped'].includes(t.state)?rb('Открыть работу','open-task',false,`data-value="${t.id}"`):rl('Результат','r0-board',s.estate)}</div>`).join('')||'<p>План пока пуст. Fabric предложит шаг из обзора проекта.</p>'}<div class="r0-footer">${rb('Обсудить следующий шаг','plan-chat',true)}</div>`)+detail('Как устроен план',`<p>Цель → задачи → запуски → результаты. История решений и зависимости принадлежат проекту, даже если исполнитель меняется.</p>${s.history.filter(e=>e.project===p.id).map(e=>`<p>${re(e.title)}</p>`).join('')}`)}
function r0Settings(s){return r0Title('Настройки Fabric','Главное — кто выполняет работу и что ему разрешено.')+`<div class="r0-dashboard">${card('Ваш CEO',`${r0Persona(s)}${hint('В макете изменения живут до перезагрузки.')}`)}${card('Базовый исполнитель',`<strong>${providerName(s.provider)}</strong><p>${s.readiness==='ready'?'Подключён':'Нужно проверить подключение'}</p>${rl('Выбрать или переподключить','r0-provider',s.estate)}`)}${card('Полномочия по умолчанию',`<p>Изучать выбранные источники и предлагать действия.</p>${detail('Когда нужно ваше решение','<p>Первый запуск изменений, расширение доступа, внешняя публикация и неоднозначная цель требуют явного решения. Настройка другого исполнителя не расширяет права.</p>')}`)}${card('Источники проекта',`${current(s)?sourceList(current(s)):'<p>Проект ещё не выбран.</p>'}${rl('Добавить папку','r0-source',s.estate)}`)}</div>`}
const r0ScreenRows=[['r0-setup','01','Познакомиться с Fabric','Знакомство → исполнитель','Fabric объясняет; человек подключает'],['r0-provider','02','Подключить исполнителя','Проверка → папка','Система проверяет; человек входит в аккаунт'],['r0-source','03','Выбрать проект','Папки → главный и связанные','Человек выбирает границу чтения'],['r0-discovery','04','Изучить проект','Источники → обзор','CEO собирает факты; исполнитель читает'],['r0-project','05','Понять проект','Инсайт → первая задача','CEO предлагает; человек выбирает цель'],['r0-plan','06','Начать работу','Задача → запуск','CEO раскладывает; исполнитель выполняет'],['r0-work','07','Работать и продолжать','Стоп → контекст → другой запуск','Система подтверждает; человек выбирает'],['r0-board','08','Принять решение','Разговор → итог → задача','Человек решает; CEO сохраняет связь'],['r0-home','09','Вернуться в контекст','Доска → агенты → продолжение','CEO показывает изменения и следующий шаг'],['r0-settings','10','Настроить работу','Образ, стиль, исполнитель, полномочия','Человек задаёт границы'],['r0-memory','12','Найти прошлую работу','Поиск → источник → разговор','Система ограничивает доступ; CEO объясняет'],['r0-guide','11','Освоить следующий шаг','Короткий пример → рабочий экран','Помощь раскрывается по потребности']]
function r0Map(s){return r0Title('Первый релиз · карта экранов','От знакомства с Fabric до возвращения в работу. Нажмите любой этап, чтобы проверить его в макете.')+`<div class="r0-footer">${rb('Открыть заполненный пример','example')}${rb('Команда в двух проектах','team-example')}${rl('Пройти первый запуск','r0-setup',s.estate)}</div><div class="r0-map">${r0ScreenRows.map(([v,n,title,next,owner])=>`<a class="r0-map-node" href="#view-${v}?estate=${encodeURIComponent(s.estate)}"><span class="r0-step">${n}</span><h3>${title}</h3><p>${next}</p><small>${owner}</small><span aria-hidden="true">↗</span></a>`).join('')}</div>${detail('Что остаётся за пределами этого макета','<p>Исторические и расширенные экраны сохранены в полном каталоге. Здесь — маршрут первого выпуска. Переходы демонстрационные: готовность настоящих агентов, файловые разрешения, остановка процессов и сохранение после перезапуска требуют нативной реализации.</p><a class="button" href="#screens">Полный каталог</a>')}`}
function r0Guide(s){return r0Title('Осваивайте Fabric по ходу работы','Каждый следующий шаг помогает в вашем проекте.')+`<div class="r0-map">${[['Первый вход','Выберите исполнителя и папку. Fabric сам соберёт обзор.','r0-source'],['Первая задача','Примите полезный следующий шаг, затем запустите работу.','r0-plan'],['Первое возвращение','Откройте «Где остановились»: изменения и следующий шаг уже рядом.','r0-home'],['Когда нужен человек','Разберите вопрос на доске или отложите до следующего обзора.','r0-board'],['Когда агент завис','Остановите, дождитесь подтверждения, продолжите новой сессией.','r0-work'],['Разговор с CEO','Пишите или диктуйте; проект выбран над полем ввода.','r0-project']].map(([title,body,v])=>card(title,`<p>${body}</p>${rl('Попробовать',''+v,s.estate)}`)).join('')}</div>${rb('Спросить Fabric','chat')}`}
function r0Chat(s){const key=chatKey(s),b=ticket(s),messages=s.messages[key]||[],c=chatWorkspaceState(s);return `<aside class="r0-chat" role="dialog" aria-modal="false" aria-label="Чат с ${re(s.name)}"><header>${avatar(s,true)}<div><strong>${re(s.name)}</strong><p class="meta">${b?re(s.projects.find(p=>p.id===b.project)?.name)+' · '+re(chatSubjectSnapshot(s,b)?.title||b.title):'Ваш CEO'}</p></div>${chatIconButton('История разговоров','cw-history','history')}${chatIconButton('Новый разговор','new-chat','new')}${chatIconButton('Свернуть чат','close-chat','minus')}</header><div class="r0-chat-log" role="log" aria-live="polite">${messages.length?messages.map((m,i)=>`<article class="r0-message ${m.role}"><small>${m.role==='user'?'Вы':re(s.name)+' · пример целевого ответа'}</small><p>${re(m.text)}</p>${m.role==='user'?renderChatAttachments(m.context?.attachments):''}${renderChatWidget(s,m,i)}</article>`).join(''):`<div class="r0-chat-welcome"><h3>С чего начнём?</h3><p>Разберём, что происходит,<br>и выберем следующий шаг.</p><div class="cw-shortcuts">${['Что изменилось?','Предложи план','Создай задачу'].map(t=>rb(t,'chat-prompt',false,`data-value="${t}"`)).join('')}</div></div>`}${outcomeCard(s,b)}${renderChatKnowledge(s)}${renderChatHistory(s)}${renderChatTray(s)}</div><div class="r0-composer">${renderChatContext(s)}${renderChatAttachments(c.attachments,true)}<div class="cw-input"><label class="sr-only" for="r0-message">Сообщение Fabric</label><textarea id="r0-message" data-r0-field="chatDraft" rows="1" placeholder="Спросите или поручите…">${re(s.drafts[key]||'')}</textarea><div class="cw-compose-actions">${chatIconButton(s.voice==='recording'?'Остановить запись':'Продиктовать',s.voice==='recording'?'voice-stop':'voice',s.voice==='recording'?'stop':'mic')}${chatIconButton('Отправить','send','send',`${!(s.drafts[key]||'').trim()&&!c.attachments.length?'disabled':''}`)}</div></div>${c.error?`<p class="cw-status" role="alert">${re(c.error)}</p>`:''}${s.notice?`<p class="cw-status" role="status">${re(s.notice)}</p>`:''}${s.voice==='recording'?'<p class="cw-status" role="status">Пример записи · микрофон выключен</p>':s.voice==='review'?'<p class="cw-status" role="status">Пример расшифровки · проверьте перед отправкой</p>':''}</div></aside>`}
function r0Persona(s){return `<section class="r0-preferences" aria-label="Профиль Fabric">${avatar(s,true)}<label class="field">Имя<input data-r0-field="name" value="${re(s.name)}" maxlength="40" placeholder="Fabric"></label><fieldset><legend>Облик</legend>${[['0','Север'],['1','Лес'],['2','Закат']].map(([v,n])=>rb(n,'avatar-style',false,`data-value="${v}" aria-pressed="${s.avatar===Number(v)}"`)).join('')}</fieldset><fieldset><legend>Стиль общения</legend>${[['concise','Кратко'],['balanced','По делу'],['detailed','Подробно']].map(([v,n])=>rb(n,'style',false,`data-value="${v}" aria-pressed="${s.style===v}"`)).join('')}</fieldset><dl class="r0-facts"><div><dt>Проекты</dt><dd>${s.projects.length}</dd></div><div><dt>Решения</dt><dd>${s.board.flatMap(b=>[...(b.outcomes||[]),...(b.outcome?[b.outcome]:[])]).filter(o=>o.applied).length}</dd></div><div><dt>События</dt><dd>${s.history.length}</dd></div></dl><p class="meta">Статистика текущего примера</p></section>`}
const startupExamples = [['ready','Совместимая база'],['behind','Старая база'],['ahead','Новая база'],['unreadable','Нет ответа'],['manifest','Неизвестная сборка']]
function startupPreview(s){
 const reason={behind:['Нужно обновить базу','Установленная версия базы не подходит этой сборке. Обновите её по плану миграции и повторите проверку.'],ahead:['Нужна совместимая сборка','База новее, чем поддерживает эта версия Fabric. Установите совместимую сборку и откройте приложение заново.'],unreadable:['Не удалось проверить базу','Проверьте соединение с локальной базой и повторите проверку.'],manifest:['Не удалось проверить сборку','Установите проверенную сборку и откройте приложение заново.']}[s.startupExample]
 return r0Title(reason[0],'Рабочее пространство ещё не запущено.')+`<section class="r0-card" aria-label="Проверка перед запуском"><p>${reason[1]}</p><p class="meta">Сохранённая работа не изменена. В этом запуске Fabric не запускал агентов.</p>${['behind','unreadable'].includes(s.startupExample)?rb('Повторить проверку','startup-retry',true):''}${s.startupRetry?'<p role="status">Проверка пока не пройдена. Причина остаётся той же.</p>':''}<p class="meta">Пример ошибки перед запуском · системные данные не читаются. Другой результат можно выбрать в инструментах макета.</p></section>`
}
export function renderFirstRelease(view,state={},model={}) {
 if(!firstReleaseViews.includes(view)&&!['launch-start','onboarding'].includes(view))return null
 const requestedView=view;const s=firstReleaseStore(state);const startupBlocked=s.startupExample&&s.startupExample!=='ready';const missingProject=['r0-project','r0-plan','r0-work','r0-memory'].includes(view)&&String(state.project||'').startsWith('r0-project-')&&!s.projects.some(p=>p.id===state.project);if(!startupBlocked&&!missingProject&&String(state.project||'').startsWith('r0-project-'))s.selected=state.project;if(['launch-start','onboarding'].includes(view))view=!s.configured?'r0-setup':s.readiness==='ready'?'r0-source':'r0-provider'
 let body=startupBlocked?startupPreview(s):({'r0-setup':r0Setup,'r0-provider':r0Provider,'r0-source':r0Source,'r0-discovery':r0Discovery,'r0-home':r0Home,'r0-project':r0Project,'r0-work':r0Work,'r0-board':r0Board,'r0-plan':r0Plan,'r0-settings':r0Settings,'r0-map':r0Map,'r0-guide':r0Guide,'r0-memory':renderMemoryWorkspace}[view])(s)
 const read=startupBlocked?'error':missingProject?'unknown':state.state||'ready';if(read!=='ready'){const messages={loading:'Читаем сохранённое состояние…',denied:'Нет доступа к этому пространству.',error:'Не удалось прочитать состояние.',partial:'Доступна только часть источников.',conflict:'Состояние изменилось. Перечитайте его перед действием.',stale:'Показан последний сохранённый снимок.',unknown:'Исход операции пока неизвестен.',empty:'Здесь пока нет сохранённой работы.'};body=r0Title(messages[read]||'Состояние недоступно','Ваши настройки и выбранная папка сохраняются.')+(read==='empty'?'<p>'+re(model.views?.find(v=>v.id===requestedView)?.empty_action?.description||'Сохранённая работа доступна и без готового исполнителя.')+'</p>'+rl('Начать с Fabric','r0-setup',s.estate):rb('Повторить чтение','read-retry',true));}
 if(startupBlocked)body=startupPreview(s)
 return `<div class="r0" data-r0-view="${view}" data-review="${s.reviewMode}"><div class="r0-topline"><a href="#view-r0-map?estate=${encodeURIComponent(s.estate)}">Первый релиз</a><span></span>${rb(s.reviewMode?'Скрыть инструменты':'Инструменты макета','review-mode')}</div>${s.notice&&read==='ready'?`<p class="r0-notice" role="status">${re(s.notice)}</p>`:''}${body}${read==='ready'?`<div class="r0-fabric-dock"><button class="r0-fabric-icon" data-r0="reopen-chat" aria-label="Открыть чат Fabric" title="Чат с Fabric" aria-expanded="${s.chat}">${avatar(s,true)}</button></div>${s.chat?r0Chat(s):''}`:''}<div class="r0-demo-tools">${detail('Проверка перед запуском · примеры',startupExamples.map(([value,label])=>rb(label,'startup-example',false,`data-value="${value}" aria-pressed="${(s.startupExample||'ready')===value}"`)).join(''))}${detail('Состояния чтения · макет',`<label class="field">Результат следующего чтения<select data-r0-field="scanOutcome">${[['done','Обзор готов'],['partial','Часть источников недоступна'],['empty','Пустой проект'],['denied','Нет доступа к папке'],['failed','Агент прервал чтение']].map(([v,l])=>`<option value="${v}" ${s.scanOutcome===v?'selected':''}>${l}</option>`).join('')}</select></label>${hint('Имитация выполняется только после вашего выбора. Системные файлы и агенты не затрагиваются.')}`)}</div></div>`
}
export function attachFirstRelease(root,options) {
 const get=()=>firstReleaseStore(options.state())
 let alive=true
 const startupBlocked=s=>s.startupExample&&s.startupExample!=='ready'
 const reviewAction=a=>['startup-example','startup-retry','review-mode'].includes(a)
 const allowed=()=>alive&&!startupBlocked(get())&&(options.state().state||'ready')==='ready'
 // Every callback belongs to the startup example that created it. Returning to
 // ready never re-authorizes an old timer, picker or clipboard completion.
 const fence=()=>{const owner=get(),epoch=owner.startupEpoch||0;return()=>allowed()&&get()===owner&&(owner.startupEpoch||0)===epoch}
 const render=()=>{const active=document.activeElement,focus=active?.dataset.r0,focusValue=active?.dataset.value,old=root.querySelector('.r0-chat-log'),scroll=old?.scrollTop||0,atEnd=!old||old.scrollHeight-old.scrollTop-old.clientHeight<64;options.rerender();const log=root.querySelector('.r0-chat-log');if(log)log.scrollTop=atEnd||chatWorkspaceState(get()).tray||chatWorkspaceState(get()).inspect||chatWorkspaceState(get()).history?log.scrollHeight:scroll;if(focus)[...root.querySelectorAll('[data-r0]')].find(el=>el.dataset.r0===focus&&el.dataset.value===focusValue)?.focus()}
 const go=v=>v?options.navigate(v,{estate:get().estate,project:get().selected||null}):render()
 const timers=new Set()
 const later=(fn,delay)=>{const valid=fence();const t=setTimeout(()=>{timers.delete(t);if(valid())fn()},delay);timers.add(t)}
 function dispatch(action,value){if(!alive||(!reviewAction(action)&&!allowed()))return;const s=get(),originProject=s.selected,next=firstReleaseAction(s,action,value);go(next)
  if(action==='probe'&&s.readiness==='checking'){const token=s.probeToken,provider=s.provider,outcome=s.probeOutcome||'ready';later(()=>{if(s.probeToken!==token||s.provider!==provider)return;firstReleaseAction(s,'probe-result',outcome);if(get()===s)render()},650)}
  if((action==='scan'||action==='candidate'||action==='candidate-import'||action==='scan-current')&&s.scan==='running'){const token=s.scanToken;for(let i=1;i<=3;i++)later(()=>{if(s.scanToken!==token)return;firstReleaseAction(s,'scan-tick');if(get()===s)render()},i*500);later(()=>{if(s.scanToken!==token)return;const destination=firstReleaseAction(s,'scan-result',s.scanOutcome||(s.pendingSource.endsWith('/empty')?'empty':'done'));if(get()===s&&root.querySelector('[data-r0-view]')?.dataset.r0View==='r0-discovery')go(destination)},2100)}
  if((action==='stop'||action==='check-stop'||action==='force-confirm'||action==='widget-command'||action==='send')&&s.run?.status==='stopping'){const run=s.run;later(()=>{if(run.status!=='stopping')return;settleStop(s,run,s.stopOutcome);s.history.unshift({id:'event-'+s.nextId++,title:run.status==='stopped'?'Получено подтверждение остановки процесса':'Остановка не подтверждена',project:run.project});if(get()===s)render()},750)}
 }
 root.addEventListener('input',e=>{if(!allowed())return;const key=e.target.dataset.r0Field;if(!key)return;const s=get();if(key==='memoryQuery'){memoryWorkspaceState(s).query=e.target.value;memoryWorkspaceState(s).selected=null;const caret=e.target.selectionStart;render();const input=root.querySelector('#memory-query');input?.focus();input?.setSelectionRange(caret,caret);}else if(key==='chatDraft'){s.drafts[chatKey(s)]=e.target.value;e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,112)+'px';const send=root.querySelector('[data-r0=send]');if(send)send.disabled=!e.target.value.trim()&&!chatWorkspaceState(s).attachments.length;}else if(key==='cwLink')chatWorkspaceState(s).link=e.target.value;else if(key==='cwSearch'){chatWorkspaceState(s).search=e.target.value;const caret=e.target.selectionStart;render();const input=root.querySelector('#cw-search');input?.focus();input?.setSelectionRange(caret,caret);}else if(['name','url','taskDraft','terminalInput'].includes(key))s[key]=e.target.value})
 root.addEventListener('change',e=>{if(!allowed())return;const key=e.target.dataset.r0Field;if(!key)return;const s=get();if(['probeOutcome','scanOutcome','stopOutcome'].includes(key))s[key]=e.target.value;if(key==='chatScope'){s.activeTicket=null;s.chatScope=e.target.value;s.voice='idle';render()}})
 root.addEventListener('click',e=>{const b=e.target.closest('[data-r0]');if(!b||b.disabled)return;const a=b.dataset.r0,s=get();
  if(!alive)return;
  if(reviewAction(a)){dispatch(a,b.dataset.value||'');return}
  if(a==='read-retry'&&!startupBlocked(s)){options.navigate(root.querySelector('[data-r0-view]').dataset.r0View,{state:'ready'});return}
  if(!allowed())return;
  if(a==='pick-folder'){const valid=fence();options.pickFolder(path=>{if(!valid()||!path)return;firstReleaseAction(s,'picked',path);dispatch('scan')});return}
  if(a==='reopen-chat'&&s.chat){root.querySelector('#r0-message')?.focus();return}
  if(a==='focus-chat'){root.querySelector('#r0-message')?.focus();return}
  if(a==='chat'||(a==='reopen-chat'&&!Object.keys(s.messages).length&&!Object.keys(s.drafts).length&&!s.activeTicket)){s.chatScope=['r0-home','r0-map','r0-setup','r0-provider','r0-source','r0-settings'].includes(root.querySelector('[data-r0-view]')?.dataset.r0View)?'':s.selected||'';dispatch(a);root.querySelector('#r0-message')?.focus();return}
  if(a==='close-chat'){dispatch(a);root.querySelector('.r0-fabric-dock [data-r0]')?.focus();return}
  if(a==='chat-prompt'){const key=chatKey(s),draft=s.drafts[key]||'';s.drafts[key]=draft.trim()?draft+'\n'+b.dataset.value:b.dataset.value;if(draft.trim())render();else dispatch('send');root.querySelector('#r0-message')?.focus();return}
  if(a==='team-filter'){dispatch(a,{filter:b.dataset.value,project:b.dataset.project});return}
  if(['outcome-apply','outcome-decline','outcome-run'].includes(a)){dispatch(a,{ticket:b.dataset.value,proposal:b.dataset.proposal,source:'button'});return}
  if(a==='cw-command'){dispatch('widget-command',{index:Number(b.dataset.message),project:b.dataset.value,source:'button'});return}
  if(a==='chat-command'){if(!s.chatScope){s.notice='Выберите проект.';render();return}s.selected=s.chatScope;if(b.dataset.value==='plan'){go('r0-plan');return}if(b.dataset.value==='task'){const source=s.messages[s.chatScope].find(m=>m.command==='task'&&m.prompt===b.dataset.prompt);if(source?.ticketId){dispatch('open-ticket',source.ticketId);return}firstReleaseAction(s,'topic',redactFixtureMessage(b.dataset.prompt));if(source)source.ticketId=s.activeTicket;s.drafts[chatKey(s)]=b.dataset.prompt;dispatch('send');return}dispatch(b.dataset.value,'');return}
  if(a==='copy-context'){const valid=fence();const text=root.querySelector('.r0-work-bar')?.innerText+'\n'+root.querySelector('.r0-dashboard aside .r0-card')?.innerText;navigator.clipboard.writeText(text).then(()=>{if(!valid())return;s.notice='Контекст скопирован.';render()},()=>{if(!valid())return;s.notice='Не удалось скопировать. Выделите текст в панели контекста.';render()});return}
  if(a==='terminal-send'){if(s.run?.status==='running'&&s.terminalInput?.trim()){record(s,'Уточнение исполнителю: '+redactFixtureMessage(s.terminalInput));s.notice='Уточнение записано в журнал примера.';s.terminalInput='';render()}return}
  dispatch(a,b.dataset.value||'');if(['open-ticket','topic','plan-chat','discuss','reopen-chat','send','memory-chat'].includes(a))root.querySelector('#r0-message')?.focus()
 })
 root.addEventListener('keydown',e=>{if(!allowed())return;if(e.target.id==='r0-message'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();dispatch('send');root.querySelector('#r0-message')?.focus();return}if(e.key==='Escape'&&get().chat){e.preventDefault();get().chat=false;render();root.querySelector('.r0-fabric-dock [data-r0]')?.focus()}})
 return {dispatch,dispose:()=>{alive=false;for(const t of timers)clearTimeout(t);timers.clear()}}
}

// SCR-64 · SCN-042 first slice: every send state of the one conversation, drawn with
// the same chat component as the overlay. Until the CEO worker exists a message is
// kept, never answered, so no state here shows a reply.
const ceoConversationStates=[['not-activated','Не включён'],['empty','Пусто'],['saved-locally','Сохранено на Mac'],['accepted-pending','Сохранено без ответа'],['commit-unknown','Результат неизвестен'],['refused','Не отправлено'],['recovered','Восстановлено'],['draft-conflict','Конфликт черновика'],['capacity-full','Место закончилось'],['local-recovery-required','История не читается'],['unsupported-context','Несколько проектов'],['denied','Недоступно'],['loading','Загрузка'],['error','Ошибка']]
export function renderCeoConversation(state={}){
 const s=firstReleaseStore(state),known=new Set(ceoConversationStates.map(x=>x[0])),k=known.has(state.chatState)?state.chatState:'not-activated'
 const ask='Посмотри, что изменилось в Atlas за неделю, и предложи следующий шаг.'
 const status=(text,role='status')=>`<p class="cw-status" role="${role}">${re(text)}</p>`
 const mine=(text,line,extra='')=>`<article class="r0-message user"><small>Вы</small><p>${re(text)}</p><p class="meta">${re(line)}</p>${extra}</article>`
 const btn=(label,primary=false,disabled=false)=>`<button type="button" class="button${primary?' primary':''}"${disabled?' disabled':''}>${re(label)}</button>`
 let log='',draft='',send=true,note='',scope='Без проекта'
 if(k==='not-activated'){log=`<div class="r0-chat-welcome"><h3>Разговор ещё не включён</h3><p>Черновик сохраняется на этом Mac. Отправка заработает, когда станет доступно восстановление личной истории.</p></div>`;draft=ask;send=false;note=status('Отправка выключена: восстановление личной истории пока недоступно.')}
 else if(k==='empty'){log=`<div class="r0-chat-welcome"><h3>С чего начнём?</h3><p>Опишите, что нужно. Fabric сохранит запрос и покажет, что с ним стало. Разговор можно начать с проекта или без него.</p></div>`}
 else if(k==='saved-locally'){log=`<div class="r0-chat-welcome"><h3>С чего начнём?</h3></div>`;draft=ask;note=status('Сохранено на этом Mac')}
 else if(k==='accepted-pending'){log=mine(ask,'Сохранено, ответа пока нет')}
 else if(k==='commit-unknown'){log=mine(ask,'Результат отправки неизвестен. Повторно не отправляем — проверим эту же отправку.',`<div class="actions">${btn('Проверить ещё раз')}</div>`)}
 else if(k==='refused'){log=mine(ask,'Не отправлено: нет соединения. Черновик сохранён.',`<div class="actions">${btn('Отправить снова')}</div>`)}
 else if(k==='recovered'){log=`<div class="r0-chat-welcome"><h3>С чего начнём?</h3></div>`;draft=ask;note=status('Черновик восстановлен после перезапуска')}
 else if(k==='draft-conflict'){log=`<div class="r0-chat-welcome"><h3>С чего начнём?</h3></div>`;draft=ask+' Учти ещё Orbit.';note=status('Черновик изменён в другом окне. Сохранён более новый текст.')+`<div class="actions">${btn('Скопировать мой вариант')}</div>`}
 else if(k==='capacity-full'){log=`<section class="r0-card"><h3>Хранилище на этом Mac заполнено</h3><p>Сохранено 32 черновика — это предел. Удалите ненужные, чтобы продолжить.</p><div class="r0-row"><span>Черновик · Atlas · 09:12</span>${btn('Удалить')}</div><div class="r0-row"><span>Отправка · Atlas · результат неизвестен</span>${btn('Проверить ещё раз')}${btn('Удалить',false,true)}</div><p class="meta">Отправку с неизвестным результатом нельзя удалить, пока она не проверена.</p></section>`;draft=ask;send=false}
 else if(k==='local-recovery-required'){log=`<section class="r0-card"><h3>Историю разговора не удаётся прочитать</h3><p>Это не пустой разговор: сообщения на этом Mac не удалены, но сейчас их нельзя открыть.</p><div class="actions">${btn('Проверить ещё раз')}</div></section>`;send=false}
 else if(k==='unsupported-context'){scope='Atlas';log=`<div class="r0-chat-welcome"><h3>С чего начнём?</h3></div>`;draft=ask;note=status('Эта версия работает без проекта или с одним проектом. Выбор «Все проекты» не применён.','alert')}
 else if(k==='denied'){return r0Title('Разговор с Fabric','Состояния разговора, пока Fabric не отвечает.')+ceoStatePicker(k)+`<aside class="r0-chat is-inline" aria-label="Чат с ${re(s.name)}"><header>${avatar(s,true)}<div><strong>${re(s.name)}</strong></div></header><div class="r0-chat-log"><section class="r0-card"><h3>Разговор недоступен</h3><p>У этого профиля нет доступа к разговору.</p></section></div></aside>`}
 else if(k==='loading'){log=status('Читаем разговор…')}
 else if(k==='error'){log=`<section class="r0-card"><h3>Разговор не загрузился</h3><p>Служба разговора не ответила. Черновик сохранён.</p><div class="actions">${btn('Повторить')}</div></section>`;draft=ask}
 const chips=`<div class="cw-context" role="group" aria-label="Контекст разговора">${['Без проекта','Atlas','Все проекты'].map(c=>`<button type="button" class="cw-chip" aria-pressed="${c===scope?'true':'false'}">${re(c)}</button>`).join('')}</div>`
 return r0Title('Разговор с Fabric','Состояния разговора, пока Fabric не отвечает. Каждое названо своими словами; ответ модели здесь не показан.')+ceoStatePicker(k)+`<aside class="r0-chat is-inline" aria-label="Чат с ${re(s.name)}"><header>${avatar(s,true)}<div><strong>${re(s.name)}</strong><p class="meta">${re(scope)}</p></div></header><div class="r0-chat-log" role="log" aria-live="polite">${log}</div><div class="r0-composer">${chips}<div class="cw-input"><label class="sr-only" for="cc-message">Сообщение Fabric</label><textarea id="cc-message" rows="2" placeholder="Спросите или поручите…">${re(draft)}</textarea><div class="cw-compose-actions"><button type="button" class="button primary"${send&&draft?'':' disabled'}>Отправить</button></div></div>${note}</div></aside>`
}
function ceoStatePicker(k){return `<nav class="cc-states" aria-label="Состояния разговора">${ceoConversationStates.map(([id,label])=>`<a class="chip" href="#view-ceo-conversation?chatState=${id}"${id===k?' aria-current="true"':''}>${re(label)}</a>`).join('')}</nav>`}
